// Iteration 16 (lane RUN): the logical levels of the game and their sections (levels/types.ts).
//
//  - subway: one section 'main' = the existing generateStation(levelSeed, {startWeapon}) with ZERO changes to its
//    output; the level-wide gear roll (lane GEAR) is appended to layout.pickups afterwards (no gear => identical).
//  - office: 'street' (a compact subway stop whose upper storey is the office tower lobby) + 'floor-2' … 'floor-8'
//    (one office storey each), generated by lane WORLD-GEN's generateOfficeSection(section, ctx).
// A section regenerates identically from (level seed, section): the run memory (run/memory.ts) carries what changed.

import {generateStation} from '../gen/station';
import type {StationLayout} from '../gen/stationTypes';
import {placeSectionGear} from './gearAdapter';
import {generateOfficeSection} from './officeFallback'; // TEMPORARY until gen/office/index.ts (WORLD-GEN) lands
import type {Arrival, LevelDef, LevelId, SectionGenContext, SectionKey} from './types';

/** Floors of the office tower: 1 = the lobby (upper storey of 'street'), 2..8 = office floors. */
export const OFFICE_TOP_FLOOR = 8;
export const OFFICE_SECTIONS: readonly string[] = ['street', ...Array.from({length: OFFICE_TOP_FLOOR - 1}, (_, i) => `floor-${i + 2}`)];

export const LEVEL_IDS: readonly LevelId[] = ['subway', 'office'];

/** Gear assigned to this section by the level-wide roll (lane GEAR), placed once, after generation. */
function withGear(layout: StationLayout, ctx: SectionGenContext): StationLayout {
  if (ctx.gear && ctx.gear.length) placeSectionGear(layout, ctx.gear);
  return layout;
}

export const LEVELS: Record<LevelId, LevelDef> = {
  subway: {
    id: 'subway',
    name: 'Subway',
    blurb: 'A large abandoned subway station — platforms, concourses, shops and back-of-house rooms.',
    entry: 'main',
    sections: () => ['main'],
    generate: (section, ctx) => {
      if (section !== 'main') throw new Error(`Subway has no section '${section}'`);
      return withGear(generateStation(ctx.levelSeed >>> 0, {startWeapon: ctx.startWeapon}), ctx);
    },
  },
  office: {
    id: 'office',
    name: 'Office Space',
    blurb: 'A small subway stop under an office tower — climb into the lobby, then explore the floors by elevator and stairwell.',
    entry: 'street',
    sections: () => [...OFFICE_SECTIONS],
    generate: (section, ctx) => {
      if (!OFFICE_SECTIONS.includes(section)) throw new Error(`Office Space has no section '${section}'`);
      return withGear(generateOfficeSection(section, ctx), ctx);
    },
  },
};

export function isLevelId(v: unknown): v is LevelId {
  return typeof v === 'string' && (LEVEL_IDS as readonly string[]).includes(v);
}

/** The other logical level (the pause menu's "Travel to …"). */
export function otherLevel(level: LevelId): LevelId {
  return level === 'subway' ? 'office' : 'subway';
}

/** Office floor number of a section ('street' = 1, the lobby; 'floor-5' = 5); 0 for non-office sections. */
export function floorOfSection(key: SectionKey): number {
  if (key.level !== 'office') return 0;
  if (key.section === 'street') return 1;
  const n = Number(/^floor-(\d+)$/.exec(key.section)?.[1]);
  return Number.isFinite(n) ? n : 0;
}

export function sectionForFloor(floor: number): string {
  return floor <= 1 ? 'street' : `floor-${floor}`;
}

/** Short human label of a section ("Station", "Street station and lobby", "Floor 5"). */
export function sectionLabel(key: SectionKey): string {
  if (key.level !== 'office') return 'Station';
  return key.section === 'street' ? 'Street station and lobby' : `Floor ${floorOfSection(key)}`;
}

/** What the HUD objective calls clearing this section. */
export function clearLabel(key: SectionKey): string {
  if (key.level !== 'office') return 'Station clear';
  return key.section === 'street' ? 'Street station clear' : `Floor ${floorOfSection(key)} clear`;
}

/** A player pose a section offers for an arrival (layout.office.arrivals from WORLD-GEN, else layout.playerSpawn). */
export interface ArrivalPose { x: number; z: number; yaw: number; level?: number; y?: number; source: string }

interface OfficeArrivals { arrivals?: Partial<Record<string, {x: number; z: number; yaw: number; level?: number; y?: number} | undefined>> }

export function arrivalPose(layout: StationLayout, arrival: Arrival): ArrivalPose {
  const arr = (layout as StationLayout & {office?: OfficeArrivals}).office?.arrivals;
  const kind = arrival.kind === 'return' ? 'start' : arrival.kind;
  const exact = arr?.[kind];
  if (exact) return {...exact, source: kind};
  if (arr?.start) return {...arr.start, source: 'start'};
  const sp = layout.playerSpawn as {x: number; z: number; yaw: number; level?: number; y?: number};
  return {x: sp.x, z: sp.z, yaw: sp.yaw, level: sp.level, y: sp.y, source: 'playerSpawn'};
}
